#!/bin/bash
# Generated by tools/aether_train_run.py for run gemma4-12b-v3-late-s42; do not edit by hand.
# Waits for this run's training container to exit, for no other aether-train/aether-serve
# container to run, and for the memory the served model asks for (0.85 of the device:
# vLLM's --gpu-memory-utilization), then runs score.sh and exits with its status.
# Exits 5 after 24 h short of that memory (another process holds it), and 6 without scoring
# when the trainer's divergence stop ended the run (no export will come). Logs to logs/when_ready.log.
set -u
R=$HOME/aether-train/gemma4-12b-v3-late-s42
LOG="$R/logs/when_ready.log"
mkdir -p "$R/logs"
log() { echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] $*" >> "$LOG"; }
UTIL=0.85
MAX_WAIT=86400
# "TOTAL AVAILABLE" in MiB: the GPU's own when nvidia-smi reports them; on unified memory it
# prints [N/A], and the host's available memory (free, as the driver's other gates read it)
# stands in for the device's.
memory_mib() {
  local g
  g=$(nvidia-smi --query-gpu=memory.total,memory.free --format=csv,noheader,nounits 2>/dev/null | head -1 | tr -d ' ')
  case "$g" in [0-9]*,[0-9]*) echo "${g%%,*} ${g#*,}"; return ;; esac
  free -m 2>/dev/null | awk '/^Mem:/{print $2, $7}'
}
if [ ! -f /storage/aether-train/gemma4-12b-v3-late-s42/merged_16bit/config.json ]; then
  log "waiting for the merged export /storage/aether-train/gemma4-12b-v3-late-s42/merged_16bit"
  until [ -f /storage/aether-train/gemma4-12b-v3-late-s42/merged_16bit/config.json ]; do
    DIVERGED=$(python3 -c 'import json, sys
try:
    record = json.load(open(sys.argv[1])).get('"'"'diverged'"'"')
except (OSError, ValueError, AttributeError):
    record = None
if isinstance(record, dict):
    print('"'"'diverged='"'"' + json.dumps(record, separators=('"'"','"'"', '"'"':'"'"')))
' $HOME/aether-train/gemma4-12b-v3-late-s42/train/run_metadata.json)
    if [ -n "$DIVERGED" ]; then
      log "GAVE UP: training stopped diverged and wrote no export (retrain under a new tag): ${DIVERGED#diverged=}"
      exit 6
    fi
    sleep 300
  done
fi
if [ "$(docker inspect -f '{{.State.Running}}' aether-train-gemma4-12b-v3-late-s42 2>/dev/null)" = "true" ]; then
  log "waiting for aether-train-gemma4-12b-v3-late-s42 to exit"
  while [ "$(docker inspect -f '{{.State.Running}}' aether-train-gemma4-12b-v3-late-s42 2>/dev/null)" = "true" ]; do sleep 300; done
fi
WAITED=0  # seconds spent short of memory alone; waiting for this rig's own jobs does not count
while true; do
  OTHERS=$(docker ps --format '{{.Names}}' | grep -E '^aether-(train|serve)-' | tr '\n' ' ')
  if [ -n "$OTHERS" ]; then log "not yet: other GPU jobs running: $OTHERS"; sleep 300; continue; fi
  set -- $(memory_mib)
  TOTAL=${1:-}; AVAIL=${2:-}
  if ! [[ "$TOTAL" =~ ^[0-9]+$ && "$AVAIL" =~ ^[0-9]+$ ]]; then
    log "cannot read the device's memory (nvidia-smi, free); scoring without the memory wait"; break
  fi
  NEED=$(awk -v t="$TOTAL" -v u="$UTIL" 'BEGIN { n = t * u; printf "%d", (n > int(n)) ? int(n) + 1 : n }')
  SHARE="the serve asks for $((NEED / 1024)) GiB ($UTIL of $((TOTAL / 1024)) GiB), $((AVAIL / 1024)) GiB available"
  if [ "$AVAIL" -ge "$NEED" ]; then log "memory ok: $SHARE"; break; fi
  if [ "$WAITED" -ge "$MAX_WAIT" ]; then
    log "GAVE UP after $((WAITED / 60)) min short of memory: $SHARE; free it (or lower serve.gpu_memory_utilization) and re-arm"
    exit 5
  fi
  log "waiting for memory: $SHARE; waited $((WAITED / 60)) of $((MAX_WAIT / 60)) min"
  sleep 300; WAITED=$((WAITED + 300))
done
log "scoring"
bash "$R/score.sh"
RC=$?
if [ $RC -eq 0 ]; then log "score.sh exit 0"; else log "score.sh exit $RC; see $R/score/score.log"; fi
exit $RC
